-- DIARNEC — catálogo real de Don Yeyo y DeViano (lista de precios 7/9/2026)
-- Reemplaza los productos placeholder de esas dos marcas por los SKU reales,
-- con precio_compra (PRECIO FINAL, costo con IVA) y precio_venta (PRECIO DIST.,
-- lo que DIARNEC le cobra a los comercios).
--
-- No se borran los productos viejos (mantienen historial de ventas ya generado,
-- p.ej. la venta de prueba #1): se desactivan (activo=false) para que dejen de
-- aparecer en la tienda/inventario, y se cargan los 49 productos reales como
-- catálogo activo. Stock inicial en 0 — se carga real desde el módulo de stock.

update productos set activo = false
where marca_id in (select id from marcas where nombre in ('Don yeyo', 'DeViano'));

